// Generated by Steptix — code-behind for first-test.md.
// Safe to hand-edit: entries match steps by their `source` text.
// A step whose text changes falls back to AI and is regenerated.
import { defineSteps } from 'steptix/codebehind';

export default defineSteps([
  {
    source: 'Open the sample page',
    async run({ page, step, baseUrl }) {
      await page.goto(new URL(baseUrl, page.url()).toString());
      await step.settle();
      const heading = page.getByRole('heading', { name: 'Sample page', exact: true });
      await heading.waitFor();
      step.expect(await heading.isVisible(), 'The Sample page heading is visible');
    },
  },
  {
    source: 'Type "Ada" into the Name box',
    async run({ page, step }) {
      const name = page.locator('#name');
      await name.fill('Ada');
      await step.settle();
      await page.waitForFunction(
        () => (document.querySelector('#name') as HTMLInputElement | null)?.value === 'Ada',
      );
      step.expect((await name.inputValue()) === 'Ada', 'Name field contains Ada');
    },
  },
  {
    source: 'Click Save',
    async run({ page, step }) {
      await page.getByRole('button', { name: 'Save', exact: true }).click();
      await step.settle();
      await page.locator('#message').filter({ hasText: 'Saved for' }).waitFor();
    },
  },
  {
    source: 'Check the page says "Saved for Ada"',
    async run({ page, step }) {
      const body = page.locator('body');
      await body.filter({ hasText: 'Saved for Ada' }).waitFor();
      step.expect(
        (await body.innerText()).includes('Saved for Ada'),
        'The page says Saved for Ada',
      );
    },
  },
]);
